#!/bin/bashset -euo pipefailset +m   # ensure background jobs stay in same job-control context# Determine the root directory based on the script locationROOT=$(dirname "$(readlink -f "$0")")# Optional first argument: FoXS commandFOXS_CMD="${1:-pyfoxs}"# Directory to clear before runningCLEAR_DIR="$ROOT/carbonara_runs/smarcalAlpha/fitdata"# ========= NEW: bookkeeping for clean shutdown =========PIDS=()WATCHER_PID=""cleanup() {    echo    echo ">>> Stopping Carbonara frontend..."    # Stop watcher first    if [[ -n "${WATCHER_PID}" ]]; then        kill -INT "$WATCHER_PID" 2>/dev/null || true        sleep 0.5        kill -TERM "$WATCHER_PID" 2>/dev/null || true        sleep 0.5        kill -KILL "$WATCHER_PID" 2>/dev/null || true    fi    # Stop all predictor processes explicitly    if ((${#PIDS[@]})); then        echo ">>> Stopping predictor processes (${#PIDS[@]})"        kill -INT  "${PIDS[@]}" 2>/dev/null || true        sleep 1        kill -TERM "${PIDS[@]}" 2>/dev/null || true        sleep 1        kill -KILL "${PIDS[@]}" 2>/dev/null || true    fi    echo ">>> Stopped."    exit 0}trap cleanup SIGINT SIGTERM# ======================================================# Clear the directoryecho "Clearing directory: $CLEAR_DIR"rm -rf "$CLEAR_DIR"/*mkdir -p "$CLEAR_DIR"### argv[ 1] scattering data fileScatterFile="$ROOT/carbonara_runs/smarcalAlpha/Saxs.dat"### argv[ 2] sequence file locationfileLocs="$ROOT/carbonara_runs/smarcalAlpha/"### argv[ 3] restart tag (use to start from existing prediction)initialCoordsFile="frompdb"### argv[ 4] paired distances file (can be empty)pairedPredictions="False"### argv[ 5] fixed sections file (again can be empty)fixedsections="$ROOT/carbonara_runs/smarcalAlpha/varyingSectionSecondary1.dat"### argv[ 6] number of structuresnoStructures=1### argv[ 7] request to apply hydrophobic covering WITHIN monomers will be a list of sections on which to apply it -- Currently not usedwithinMonomerHydroCover="none"### argv[ 8] kminkmin=0.01### argv[ 9] kmaxkmax=0.2### argv[ 10] kmax StartkmaxStart=0.2### argv[11] Max number of fitting stepsmaxNoFitSteps=10000### argv[12] prediction file - mol[i] in the fitting folderpredictionFile="$ROOT/carbonara_runs/smarcalAlpha/fitdata"### argv[13] scattering output filescatterOut="$ROOT/carbonara_runs/smarcalAlpha/fitdata"### argv[14] mixture list file, alist of sets of numbers indicatig the allowed set of mixture percentages of each species (e.g. dimer 20 monomer 80)mixtureFile="$ROOT/carbonara_runs/smarcalAlpha/mixtureFile.dat"### argv[15] previous fit string in form fitname/mol6Substep_10_1.dat+fitname/mol6Substep_10_2.datprevFitStr="$ROOT/carbonara_runs/smarcalAlpha/redundant"### argv[16] log file locationlogLoc="$ROOT/carbonara_runs/smarcalAlpha/fitdata"### argv[17] last line of the previous fit log, this is only used for a restart if argv[3] = TrueendLinePrevLog="null"### argv[18] is true if we want to apply affine rotations,false if not.affineTrans="False"### argv[19] is true if we want to use errors in the scattering calculation false if not.useErrors="True"# ========= NEW: backmapping backend =========BACKMAP_BACKEND="modeller"   # "modeller" or "cg2all"# Only used if BACKMAP_BACKEND="cg2all"CG2ALL_EXEC="./bin/micromamba run -p /root/micromamba/envs/cg2all convert_cg2all"# Optional: ONLY set this if you want Carbonara constraints interpreted as disulfidesDISULFIDE_CONSTRAINTS_FILE=""# ===========================================# ========= NEW: start watcher (background) =========WATCHER_SCRIPT="$ROOT/watch_and_backmap.py"BACKMAP_SCRIPT="$ROOT/backmap_cli.py"WATCHER_LOG="$predictionFile/watcher.out"if [[ ! -f "$WATCHER_SCRIPT" ]]; then    echo "ERROR: watcher script not found: $WATCHER_SCRIPT"    exit 1fiif [[ ! -f "$BACKMAP_SCRIPT" ]]; then    echo "ERROR: backmap script not found: $BACKMAP_SCRIPT"    exit 1fiWATCHER_ARGS=(    --watch-dir "$predictionFile"    --scenario-root "$ROOT/carbonara_runs/smarcalAlpha"    --backmap-script "$BACKMAP_SCRIPT"    --max-backmap 1    --defer-backmap-seconds 600    --backend "$BACKMAP_BACKEND"    --do-foxs    --foxs-py "$FOXS_CMD"    --saxs "$ScatterFile"    --max-q "$kmax")if [[ "$BACKMAP_BACKEND" == "cg2all" ]]; then    WATCHER_ARGS+=(--cg2all-exec "$CG2ALL_EXEC")fiif [[ -n "$DISULFIDE_CONSTRAINTS_FILE" ]]; then    WATCHER_ARGS+=(--disulfide-file "$DISULFIDE_CONSTRAINTS_FILE")fipython "$WATCHER_SCRIPT" "${WATCHER_ARGS[@]}" > "$WATCHER_LOG" 2>&1 &WATCHER_PID=$!echo "Watcher started (PID=$WATCHER_PID)"# ==================================================for i in {1..20}do    echo ""    echo " >> Run number : $i "    echo ""    echo "Max number of fitting steps: " $maxNoFitSteps    echo ""    # NEW: stdbuf ensures live output, PID captured    stdbuf -oL -eL \
    $ROOT/build/bin/predictStructureQvary \
        $ScatterFile \
        $fileLocs \
        $initialCoordsFile \
        $pairedPredictions \
        $fixedsections \
        $noStructures \
        $withinMonomerHydroCover \
        $kmin \
        $kmax \
        $kmaxStart \
        $maxNoFitSteps \
        $predictionFile/mol$i \
        $scatterOut/scatter$i.dat \
        $mixtureFile \
        $prevFitStr \
        $logLoc/fitLog$i.dat \
        $endLinePrevLog \
        $affineTrans \
        $useErrors \
        > "$predictionFile/run$i.out" 2> "$predictionFile/run$i.err" &    PIDS+=($!)doneechoecho ">>> All runs launched"echo ">>> Press Ctrl+C to stop everything"echowait